const e={model:"gemma4:12b",digest:"4eb23ef187e2c5462566d6a1d3bbbc2f1346d0b4327cbb66d58fffbcc9b2b05c",promptVersion:3,date:"2026-08-30",status:{"te.character.awareness.why":"reviewed","te.character.control.why":"reviewed","te.character.endurance.why":"reviewed","te.character.precision.why":"reviewed","te.character.speed.why":"reviewed","te.energy.recovery.auxiliary":"reviewed","te.energy.recovery.dominant":"reviewed","te.energy.recovery.inferior":"reviewed","te.energy.recovery.shadow":"reviewed","te.energy.recovery.tertiary":"reviewed","te.feeder.fi":"reviewed","te.feeder.ne":"reviewed","te.feeder.ni":"reviewed","te.feeder.se":"reviewed","te.feeder.si":"reviewed","te.fieldNotes.mirror":"reviewed","te.fieldNotes.vignette.feelingsMeeting":"reviewed","te.fieldNotes.vignette.grip":"reviewed","te.fieldNotes.vignette.loop":"reviewed","te.fieldNotes.vignette.mistakenForNotCaring":"reviewed","te.fieldNotes.vignette.reorg":"reviewed","te.fieldNotes.vignette.steamroller":"reviewed","te.fieldNotes.vignette.weekendPm":"reviewed","te.hero.heading":"reviewed","te.hero.subtitle":"reviewed","te.hero.tag":"reviewed","te.lab.btn.prune.label":"reviewed","te.lab.btn.prune.sub":"reviewed","te.lab.btn.replan.label":"reviewed","te.lab.btn.replan.sub":"reviewed","te.lab.btn.ship.label":"reviewed","te.lab.btn.ship.sub":"reviewed","te.lab.btn.vague.label":"reviewed","te.lab.btn.vague.sub":"reviewed","te.lab.meter.pleasure":"reviewed","te.lab.meter.stress":"reviewed","te.lab.narration.intro":"reviewed","te.lab.narration.prune":"reviewed","te.lab.narration.pruneEnd":"reviewed","te.lab.narration.pruneMid":"reviewed","te.lab.narration.replan":"reviewed","te.lab.narration.replanEnd":"reviewed","te.lab.narration.replanMid":"reviewed","te.lab.narration.ship":"reviewed","te.lab.narration.vague":"reviewed","te.lab.narration.vagueBusy":"reviewed","te.lab.narration.vagueEnd":"reviewed","te.lab.narration.vagueMid":"reviewed","te.meta.title":"reviewed","te.slot.auxiliary":"reviewed","te.slot.critical":"reviewed","te.slot.demon":"reviewed","te.slot.dominant":"reviewed","te.slot.inferior":"reviewed","te.slot.opposing":"reviewed","te.slot.tertiary":"reviewed","te.slot.trickster":"reviewed","te.zoneA.canvasAria":"reviewed","te.zoneB.heading":"reviewed","te.zoneB.lede":"reviewed","te.zoneB.railAria":"reviewed","te.zoneC.heading":"reviewed","te.zoneC.lede":"reviewed","te.zoneD.canvasAria":"reviewed","te.zoneD.heading":"reviewed","te.zoneD.kicker":"reviewed","te.zoneD.lede":"reviewed","te.zoneE.lede":"reviewed"}},a={_meta:e,"te.character.awareness.why":"muestra sus métricas, no su funcionamiento — la auditoría vive fuera","te.character.control.why":"organizado en torno a objetivos explícitos: va hacia donde se le apunta","te.character.endurance.why":"diseñado para el rendimiento, sostenido por el progreso visible","te.character.precision.why":"Te sacrifica la elegancia en favor de la velocidad: tolerancias aceptables, enviadas","te.character.speed.why":"cadencia externa: medir, decidir, siguiente","te.energy.recovery.auxiliary":"Recuperación rápida y limpia una vez que el plan sale de sus manos.","te.energy.recovery.dominant":"Se recarga a medida que las cosas se completan: cada hito alcanzado devuelve un poco de energía.","te.energy.recovery.inferior":"La repisa de la resaca: ~30 min en los que todo el sistema funciona con poca intensidad.","te.energy.recovery.shadow":"Incompleto — parte de la carga simplemente no regresa hoy.","te.energy.recovery.tertiary":"Una recarga más lenta; la organización tiene que detenerse realmente primero.","te.feeder.fi":{figure:"El emisor brilla, pero el cabezal de construcción no tiene nada para atornillar.",mechanism:"Fi — sentimiento introvertido — es una función de juicio, por lo que entrega a Te veredictos sobre lo que importa en lugar de observaciones sobre lo que es. Casi nada llega que pueda medirse, y estas dos se sitúan en el mismo eje: lo que una acepta, la otra tiende a desconfiar. Las pilas alternan juicio con percepción precisamente por esta razón.",pair:"Juicio alimentando a juicio",provenance:"myers"},"te.feeder.ne":{figure:"Las bahías se abren a lo largo de todo el encuadre mientras la cabeza de construcción acelera; el contador sube a intervalos.",mechanism:"Ne — intuición extravertida — entrega a Te más posibilidades abiertas de las que puede terminar. Los proyectos empiezan en todas partes, la estructura se extiende y el trabajo terminado se desmorona silenciosamente tras la atención invertida hacia adelante. Alta producción, mucho desecho — Te terciaria gestionada por un percibidor dominante dos niveles por encima de ella.",pair:"el acoplamiento ENFP (Te dos plantas abajo)",provenance:"grant"},"te.feeder.ni":{figure:"El andamio se eleva, delgado y alto, apuntando hacia una bandera fuera de campo.",mechanism:"Ni — intuición introvertida — entrega pocos aportes, cada uno grande y ya convergido: una lectura de hacia dónde va todo esto. Te construye hacia esa lectura durante años — alta, estrecha, sin prisas — ejecutando contra un objetivo que nadie más puede ver aún.",pair:"la pareja ENTJ · INTJ",provenance:"myers"},"te.feeder.se":{figure:"Cuadros rápidos y bajos, elevados y golpeados el mismo día.",mechanism:"Se — percepción extravertida — entrega lo que está físicamente aquí ahora mismo, y Te lo organiza sobre la marcha. La estructura es corta, rápida y desechable: lo que tienes delante se organiza perfectamente y para mañana no queda ninguna estructura permanente.",pair:"La combinación ISFP · ESFP",provenance:"grant"},"te.feeder.si":{figure:"Un andamio amplio y uniforme, cada bahía con el mismo tramo probado.",mechanism:"Si — percepción sensorial introvertida — entrega el registro probado: lo que se hizo antes, lo que funcionó, cuál es el estándar. Te construye de forma amplia, regular y comprobable — listas de comprobación, precedentes, piezas con clasificaciones de carga conocidas. Nada exótico, y nada que falle un martes.",pair:"la combinación ESTJ · ISTJ",provenance:"myers"},"te.fieldNotes.mirror":{figure:"Una estructura detrás de los ojos, otra en el horizonte.",mechanismHtml:'Mismo elemento, actitud opuesta — y la diferencia es donde reside la estructura. <strong>Ti</strong> pregunta <em>"¿es verdad?"</em> y construye una estructura privada que nadie más puede inspeccionar; <strong>Te</strong> pregunta <em>"¿funciona?"</em> y construye en público, donde el mundo puede devolver un número. Ti cambia velocidad por coherencia; Te cambia coherencia por tracción.',provenance:"jung"},"te.fieldNotes.vignette.feelingsMeeting":{figure:"El andamio espera frente a la puerta del dormitorio.",kind:"el instrumento incorrecto",mechanism:'Un compañero que dice "no quiero que lo arregles, quiero que me escuches" le ha entregado a Te una tarea sin entregable, y la herramienta se detiene: puede medir, planificar y cerrar, y ninguna de esas es la petición. Si se ejecuta, produce acciones para un duelo —correcto, con coste y fuera de lugar-. Lo medible es la jurisdicción completa de esta función; la velada en cuestión se rige en otro lugar.',provenance:"community",title:"La Reunión de Sentimientos"},"te.fieldNotes.vignette.grip":{figure:"Una construcción apresurada con las líneas de plomo desalineadas.",kind:"la garra",mechanism:"Un INFP bajo presión se vuelve repentinamente rígido y procedimental —hojas de cálculo a las 2 a.m., un veredicto duro sobre quién está cumpliendo con su parte y una frialdad que sobresalta a todos, incluyéndolos a ellos. Esta es la garra: Te inferior en erupción cuando la dominante está agotada.",provenance:"quenk",title:"La erupción inferior"},"te.fieldNotes.vignette.loop":{figure:"La construcción se acelera con la bandera fuera de vista.",kind:"el bucle",mechanism:"Bajo estrés, la Te dominante de un ENTJ se empareja con la Se terciaria —ambas orientadas hacia fuera, con la visión a largo plazo de Ni eliminada entre ellas. Cortar, ejecutar, comprar, mover: competencia implacable sin nadie que pregunte si el objetivo sigue siendo el correcto. Este patrón de misma dirección se llama bucle.",provenance:"community",title:"El bucle"},"te.fieldNotes.vignette.mistakenForNotCaring":{figure:"El cuidado, en esta mano, parece una lista de verificación completada.",kind:"malinterpretado",mechanism:"La Te se suele confundir con falta de interés porque se manifiesta como logística: los neumáticos revisados antes de tu viaje, la cita reservada antes de que la mencionaras dos veces, el papeleo del seguro del amigo moribundo hecho de la noche a la mañana. La señal está en hacia dónde fluye el rendimiento. Observa cuyos problemas se siguen resolviendo silenciosamente, y el sentimiento se vuelve legible —escrito en una notación que la sala confundió con administración.",provenance:"community",title:"Confundido con falta de interés"},"te.fieldNotes.vignette.reorg":{figure:"El contador subió; el gráfico nunca parpadeó.",kind:"tipo de avistamiento",mechanism:"Un usuario de Te dominante reestructura un equipo con dificultades en una semana. Las líneas de reporte son más claras, las cifras mejoran y tres personas descubren que sus puestos cambiaron según un organigrama. Ambas partes de esa frase son Te.",provenance:"community",title:"La reorganización"},"te.fieldNotes.vignette.steamroller":{figure:"El andamio se levanta donde encaja, incluso sobre las puntas de los pies.",kind:"la acusación",mechanism:"Lo que la sala informa: aplanado. Lo que está ocurriendo: Te externaliza la estructura para acabar con la ambigüedad, porque para esta función una pregunta sin decidir es un coste que todos en el edificio pagan cada hora. El veredicto no estaba dirigido a nadie —que es precisamente la queja, y lo que Te madura aprende a presupuestar: las personas no son partidas de gastos, y estar programado se siente diferente a ser visto.",provenance:"community",title:"La apisonadora"},"te.fieldNotes.vignette.weekendPm":{figure:"Las bahías terminaron de forma brillante y luego se dejaron llevar por el clima.",kind:"como terciaria",mechanism:"Te terciaria en un ENFP o ESFP: ráfagas de organización formidable al servicio de lo que sea que el percibidor dominante se haya enamorado este mes. El festival obtiene una hoja de cálculo, la banda una LLC, el viaje un itinerario por colores: competencia ejecutiva genuina, activada tarde, ejecutada intensamente y retirada en el momento en que el interés que la convocó pasa a otra cosa.",provenance:"grant",title:"El gestor de proyectos de fin de semana"},"te.hero.heading":"La arquitectura de {fn}","te.hero.subtitle":"Un andamio erigido contra el mundo — clasificando lo que funciona de lo que no, y construyendo hacia la meta.","te.hero.tag":"pensamiento extravertido","te.lab.btn.prune.label":"Medir una sección con bajo rendimiento","te.lab.btn.prune.sub":"marcado y cortado de golpe","te.lab.btn.replan.label":"El objetivo cambia","te.lab.btn.replan.sub":"nuevo objetivo, misma tarde","te.lab.btn.ship.label":"Envíalo y el resultado será bueno","te.lab.btn.ship.sub":"el mundo devuelve un número","te.lab.btn.vague.label":"Recibir una afirmación inmedible","te.lab.btn.vague.sub":"esto importa, pero no puedo mostrártelo","te.lab.meter.pleasure":"Satisfacción del rendimiento","te.lab.meter.stress":"Estrés del sistema","te.lab.narration.intro":"Haz clic en un evento para enviar feedback a Te y observa qué hace la estructura cuando los números regresan — y con material que no tiene ningún número en absoluto.","te.lab.narration.prune":{figure:"— la sección parpadea, marcada donde se encuentra —",mechanism:"La medición recae sobre una sección que ha estado rindiendo poco de forma silenciosa. El veredicto no requiere argumento y no escucha defensa —",provenance:"currents"},"te.lab.narration.pruneEnd":{figure:"...el rendimiento vuelve a estabilizarse en un nivel superior al anterior.",mechanism:"La eliminación no es daño aquí: la estructura que queda funciona mejor que la que incluía el fallo. No se lamentó nada. Esta es la versión de Te de tener razón.",provenance:"currents"},"te.lab.narration.pruneMid":{figure:"— los miembros son expulsados por completo, la brecha se cierra con un chasquido y todo lo que está aguas abajo se desplaza hacia arriba para rellenarla.",mechanism:"Lo que no cumple la medida se elimina, inmediata y completamente, para que el resto pueda asumir la carga.",provenance:"currents"},"te.lab.narration.replan":{figure:"El estrés inunda el escenario —",mechanism:"El objetivo acaba de moverse — el plazo, el objetivo, o ambos. Cada juicio que el plan codificó está ahora sujeto a revisión a la vez, y la construcción en curso deja de importar en la forma que tiene.",provenance:"currents"},"te.lab.narration.replanEnd":{figure:"...un tramo diferente, una altura distinta, apuntando hacia otro lugar.",mechanism:"El plan se ha reformulado en torno al nuevo objetivo. Te no lamenta el plan anterior; vuelve a orientarlo y empieza a contar de nuevo desde aquí. Esa velocidad es toda la ventaja — y todo el coste.",provenance:"currents"},"te.lab.narration.replanMid":{figure:"— se golpean las bahías a medio construir, cae un piso, el andamio se desgarra hasta lo que aún puede alcanzarse.",mechanism:"El alcance se corta sin sentimiento: lo que no sirva al nuevo objetivo se descarta, sin importar cuánto haya costado construirlo.",provenance:"currents"},"te.lab.narration.ship":{figure:"La bahía se bloquea, la cabeza de construcción salta y el contador se mueve.",mechanism:"Un plan se encontró con el mundo y el mundo dijo que sí. Este es el feedback sobre el que funciona Te — no la elegancia, ni la certeza, sino la evidencia: funcionó, y hay un número que lo dice.",provenance:"currents"},"te.lab.narration.vague":{figure:"El material deriva de forma suave y cerrada, sin bordes que el clasificador pueda atrapar...",mechanism:"Alguien dice: esto importa, y no puedo mostrarte un número para ello. Te ha recibido una afirmación en el único formato que no puede procesar: nada para ordenar, nada para contrastar.",provenance:"currents"},"te.lab.narration.vagueBusy":"Algo inmedible ya está suelto en la cámara, y el carril va lento por ello. Deja que salga antes de enviar otro.","te.lab.narration.vagueEnd":{figure:"...se muestra exactamente igual de suave que cuando llegó.",mechanism:"La afirmación queda sin procesar — no porque fuera falsa, sino porque esta función solo acepta lo que puede contarse, y esa era la forma incorrecta. Cada usuario de Te ha echado algo real por esta puerta.",provenance:"currents"},"te.lab.narration.vagueMid":{figure:"La máquina se lo pasa a sí misma, una y otra vez.",mechanism:"La afirmación se prueba contra cada espacio que el sistema tiene, y ninguno de ellos la acepta. No hay medida para ubicarla, así que se sigue devolviendo mientras el estrés sube silenciosamente.",provenance:"currents"},"te.meta.title":"Te — Pensamiento Extravertido · CURRENTS","te.slot.auxiliary":{example:"Un INTJ lleva una lectura de diez años del campo, y este asiento la convierte en el plan de contratación del próximo trimestre.",figure:"Un andamio de cuatro quintos, construido en elevaciones planificadas en lugar de de forma continua.",mechanism:"En el segundo asiento, Te es el brazo ejecutivo de una función de percepción dominante: la lectura larga de Ni o el registro probado de Si se convierten en un plan con fechas. La organización es deliberada y está al servicio de algo —estructura levantada cuando es necesaria, no por sí misma.",provenance:"myers"},"te.slot.critical":{example:"Un ESTP termina una semana perfectamente buena ensayando todo lo que no se hizo, sin abrir el calendario.",figure:"Un contador de pulsaciones que solo cuenta hacia atrás.",mechanism:"En el sexto asiento, Te se vuelve hacia adentro como un auditor de eficiencia: estás desorganizado, pierdes tiempo, mira lo poco que terminaste realmente. Las auditorías son esporádicas y duras, dirigidas sobre todo hacia uno mismo, y mejores emitiendo veredictos que produciendo un plan.",provenance:"beebe"},"te.slot.demon":{example:"A las 3 a.m., un ESFJ calcula cada favor que ha hecho este año y concluye que nadie lo mantendría.",figure:"Un andamiaje esquelético desmontando sus pisos inferiores para seguir construyendo el superior.",mechanism:"El octavo asiento es el más raro y peor. Cuando hay una erupción —normalmente al final de una mala racha— reduce a las personas a producción: relaciones auditadas por retorno, el valor propio calculado en resultados y hallado insuficiente, en una voz que se llama a sí misma objetiva. Es el asiento menos practicado en la pila, no es una auditoría que cuente.",provenance:"beebe"},"te.slot.dominant":{example:"Para la segunda reunión el proyecto ya tiene un plan, y para el viernes el plan tiene un gráfico de reducción de trabajo que nadie pidió.",figure:"CURRENTS representa esto como un andamio a plena extensión: elevándose con rapidez, metronómico, con la bandera moviéndose mientras los barcos de trabajo avanzan.",mechanism:"En el primer asiento, Te organiza el mundo sin que se le pida: objetivos, secuencias, propietarios y fechas se organizan en torno a cualquier problema que permanezca estático, todo el día, a bajo coste. Las decisiones se cierran rápido porque la prueba es externa: ¿funcionó?, ¿qué dice el número? El precio es lo que los números pasan por alto.",provenance:"myers"},"te.slot.inferior":{example:"Un INFP en plena crisis reorganiza toda la cocina a las 2 a.m. y califica en voz alta la utilidad del hogar.",figure:"Un pequeño andamio montado a toda prisa: las uniones crujen y las plomadas están desviadas.",mechanism:"En el cuarto asiento, Te tiene el coste más alto por uso y se usa menos. Las métricas se resisten como reductivas durante largos periodos; bajo estrés prolongado, el asiento puede tomar el control y producir listas frenéticas y juicios duros sobre la competencia, con una voz que no suena como ellos — la erupción que Quenk llama la garra.",provenance:"quenk"},"te.slot.opposing":{example:"Al recibir un nuevo flujo de trabajo, un ISTP envía una alternativa completa por la mañana y pierde el interés una vez que es reconocida.",figure:"Bajo la línea de flotación del raíl, un segundo andamio se eleva junto al primero, de forma deliberada.",mechanism:"El quinto asiento abre la sombra — las cuatro posiciones que una persona ejecuta rara vez, y mayormente sin notarlo. Aquí Te despierta como un contra-organizador: cuando el proceso de otro anula su propio marco, aparece un plan rival, con números rivales y un calendario rival — menos para terminar el trabajo que para rechazar ser gestionado.",provenance:"beebe"},"te.slot.tertiary":{example:"La hoja de cálculo para el festival se construye a la 1 a.m. y es perfecta; la carpeta de impuestos sigue siendo una caja de zapatos.",figure:"Un andamio de tamaño medio con algunas bahías bellamente acabadas y suelo desnudo entre ellas.",mechanism:"En el asiento terciario, la competencia llega en ráfagas: habilidad de organización real en los pocos dominios que le importan —activada tarde, ejecutada con intensidad— e indiferencia casi total al orden en cualquier otro lugar. Se estabiliza notablemente con la edad.",provenance:"grant"},"te.slot.trickster":{example:"Al pedirle que registre las horas, un INFJ lo anota todo, incluido el acto de registrarlo, hasta que el informe resulta ilegible — sinceramente.",figure:"El andamio se ensambla en una unión imposible: técnicamente conectado, estructuralmente inútil.",mechanism:"En el séptimo asiento, el proceso se registra como un juego amañado. Las métricas y los organigramas se eluden con vaguedad, o se cumplen tan literalmente que el sistema se rompe — y la persona realmente no ve el plazo que se le acusa de incumplir. La ceguera es real, no táctica.",provenance:"beebe"},"te.zoneA.canvasAria":"Representación visual interactiva de Extraverted Thinking como un andamio que se ensambla hacia una bandera de hito","te.zoneB.heading":"Las ocho caras de Te","te.zoneB.lede":"El lienzo representa a Te como un andamio: una estructura erigida en público, probada por los resultados. El lugar donde Te se sitúa en la pila de una persona —el orden fijo en el que aparecen sus ocho funciones— cambia la forma en que construye. Haz clic en una posición para ver el cambio y observa el contador de rendimiento: cuenta la historia antes que el pie de foto. Desliza el control de madurez para ver cómo los asientos inferiores ganan fidelidad con la edad.","te.zoneB.railAria":"Posiciones de la pila para Te","te.zoneC.heading":"¿Qué alimenta a Te?","te.zoneC.lede":"Te juzga; no recopila. El juicio introvertido se alimenta de la percepción extravertida, y el juicio extravertido de la percepción introvertida; por lo tanto, los verdaderos compañeros de Te son Ni y Si. Haz clic en una alimentadora para ver qué construye.","te.zoneD.canvasAria":"Escenario de simulación del laboratorio de verificación","te.zoneD.heading":"Laboratorio de Verificación","te.zoneD.kicker":"Zona D · laboratorio de verificación","te.zoneD.lede":"Ti verifica según su propia coherencia. Te verifica según los resultados: construye la cosa, mide lo que regresa, conserva o corta en consecuencia. Cada botón envía un tipo diferente de retroalimentación al laboratorio.","te.zoneE.lede":"Patrones de la naturaleza: cómo se manifiesta Te en la vida diaria."};export{e as _meta,a as default};
